/*
 * A093007  First nonprime number reached when iterating n under x->2*x+1.
 * https://oeis.org/A093007
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = first nonprime number generated by repeatedly * applying
 *            x -> 2*x + 1 starting from x_0 = n. (a(1) = 1, a(2) = 95, …) *
 *            The function uses the provided high‑precision primality test *
 *            is_prime_big(seq_t) (see "../utils/is_prime_big.h")
 * Range:     u8 n <= 40, u16 n <= 6448, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include "../utils/is_prime_big.h"

seq_t a(idx_t n)
{
    seq_t x = (seq_t)n;          /* current value of the sequence */
    if (!is_prime_big(x))        /* n itself is not prime -> done */
        return x;

    /* iterate x = 2*x + 1 until a composite appears */
    while (is_prime_big(x))
        x = (x << 1) + 1;       /* compute next term: 2*x + 1 */

    return x;                    /* first nonprime encountered */
}
